mapper.select:
select
,
,
,

from sch_schedule s
left join sch_shift sh on s.shift_id = sh.shift_id
left join sys_user u on s.user_id = u.user_id
left join sys_dept d on s.dept_id = d.dept_id


        and s.user_id = #{criteria.userId}


        and s.dept_id = #{criteria.deptId}


        and s.shift_id = #{criteria.shiftId}


        and s.schedule_date between #{criteria.scheduleDate[0]} and #{criteria.scheduleDate[1]}


        and s.is_locked = #{criteria.isLocked}


order by s.schedule_date desc, s.create_time desc

update.foreach:
update sch_schedule
shift_id = #{item.shiftId}, schedule_type = #{item.scheduleType}, is_locked = #{item.isLocked}, remark = #{item.remark}, update_by = #{item.updateBy}, update_time = #{item.updateTime}
where schedule_id = #{item.id}

mapper.delete:
delete from sch_schedule
where schedule_date between #{startDate} and #{endDate}

    and is_locked = 0
